"年轻":    {zh:"她看起来很年轻，其实已经四十岁了。",py:"Tā kàn qǐ lái hěn nián qīng, qí shí yǐ jīng sì shí suì le.",fr:"Elle paraît très jeune, mais elle a en fait déjà quarante ans."},
"普通":    {zh:"这是一道很普通的家常菜。",     py:"Zhè shì yī dào hěn pǔ tōng de jiā cháng cài.",fr:"C'est un plat familial très ordinaire."},
"开心":    {zh:"看到你我很开心。",             py:"Kàn dào nǐ wǒ hěn kāi xīn.",               fr:"Je suis très content de te voir."},
"当然":    {zh:"当然，你可以来参加我们的活动。",py:"Dāng rán, nǐ kě yǐ lái cān jiā wǒ men de huó dòng.",fr:"Bien sûr, tu peux venir participer à notre activité."},
"可能":    {zh:"明天可能会下雨。",             py:"Míng tiān kě néng huì xià yǔ.",             fr:"Il est possible qu'il pleuve demain."},
"一定":    {zh:"你一定要来参加我的生日聚会！", py:"Nǐ yī dìng yào lái cān jiā wǒ de shēng rì jù huì!",fr:"Tu dois absolument venir à ma fête d'anniversaire !"},
"其实":    {zh:"他看起来严肃，其实很幽默。",   py:"Tā kàn qǐ lái yán sù, qí shí hěn yōu mò.", fr:"Il paraît sérieux, mais en fait il est très drôle."},
"一直":    {zh:"他一直在努力学习汉语。",       py:"Tā yī zhí zài nǔ lì xué xí Hàn yǔ.",       fr:"Il apprend le chinois assidûment depuis toujours."},
"怎么":    {zh:"这个字怎么读？",               py:"Zhè gè zì zěn me dú?",                     fr:"Comment lit-on ce caractère ?"},
"已经":    {zh:"他已经学了三年汉语了。",       py:"Tā yǐ jīng xué le sān nián Hàn yǔ le.",    fr:"Il étudie le chinois depuis trois ans déjà."},
"还是":    {zh:"你喝茶还是喝咖啡？",           py:"Nǐ hē chá hái shì hē kā fēi?",             fr:"Tu bois du thé ou du café ?"},
"总是":    {zh:"她总是第一个到学校。",         py:"Tā zǒng shì dì yī gè dào xué xiào.",        fr:"Elle est toujours la première arrivée à l'école."},
"马上":    {zh:"我马上就来，请稍等。",         py:"Wǒ mǎ shàng jiù lái, qǐng shāo děng.",     fr:"J'arrive tout de suite, patientez un instant."},
"尤其":    {zh:"他喜欢运动，尤其是游泳。",     py:"Tā xǐ huān yùn dòng, yóu qí shì yóu yǒng.", fr:"Il aime le sport, surtout la natation."},
"终于":    {zh:"经过努力，他终于考上了大学。", py:"Jīng guò nǔ lì, tā zhōng yú kǎo shàng le dà xué.",fr:"Après ses efforts, il a enfin réussi à entrer à l'université."},
"次":      {zh:"我去过中国两次。",             py:"Wǒ qù guò Zhōng guó liǎng cì.",             fr:"Je suis allé en Chine deux fois."},
"件":      {zh:"她买了三件新衣服。",           py:"Tā mǎi le sān jiàn xīn yī fu.",             fr:"Elle a acheté trois nouveaux vêtements."},
"条":      {zh:"他有两条裤子，一条蓝一条黑。", py:"Tā yǒu liǎng tiáo kù zi, yī tiáo lán yī tiáo hēi.",fr:"Il a deux pantalons, un bleu et un noir."},
"双":      {zh:"我买了一双白色的运动鞋。",     py:"Wǒ mǎi le yī shuāng bái sè de yùn dòng xié.",fr:"J'ai acheté une paire de baskets blanches."},
"瓶":      {zh:"他喝了一瓶水。",               py:"Tā hē le yī píng shuǐ.",                    fr:"Il a bu une bouteille d'eau."},

// ── YCT 4 ──────────────────────────────────────────────────────────────────
"辩论":    {zh:"两队进行了激烈的辩论。",     py:"Liǎng duì jìn xíng le jī liè de biàn lùn.",fr:"Les deux équipes ont mené un débat animé."},
"演讲":    {zh:"他在台上做了精彩的演讲。",   py:"Tā zài tái shàng zuò le jīng cǎi de yǎn jiǎng.",fr:"Il a fait un discours brillant sur scène."},
"表达":    {zh:"她善于表达自己的想法。",     py:"Tā shàn yú biǎo dá zì jǐ de xiǎng fǎ.",  fr:"Elle est douée pour exprimer ses idées."},
"交流":    {zh:"文化交流促进相互理解。",     py:"Wén huà jiāo liú cù jìn xiāng hù lǐ jiě.", fr:"Les échanges culturels favorisent la compréhension mutuelle."},
"描述":    {zh:"请描述一下那个人的外貌。",   py:"Qǐng miáo shù yī xià nà gè rén de wài mào.",fr:"Décrivez l'apparence de cette personne s'il vous plaît."},
